'use server'

import { revalidateTag } from 'next/cache';
import { addPost } from './lib/db';

export async function createPost(formData: FormData) {
  const title = formData.get('title');

  if (!title || typeof title !== 'string') {
    return;
  }

  // Simulate creating the post in the database
  await addPost(title);

  // Invalidate the cache for the 'posts' tag
  // This ensures the next request for data with this tag will be re-fetched
  revalidateTag('posts');
}

